// how much each kind beats its fins out of the plane like wings (0 = rows them flat like a fish)
const WING = { worm: 1, manta: 1, moth: 1, dragon: 0.9, swift: 0.85, rogue: 0.55, angler: 0.45, hunter: 0.3, puffer: 0.5 };

// per-species accent colour, lifted from each one's source rig SVG (sigil-species-rig-svgs/*.svg):
// the highlight fill every rig uses alongside its shared dark body-plate and shared #61E5BF lattice
// stroke, which this renderer always discarded in favour of one fixed teal for every species.
// `glow` is a bioluminescence floor: species that live deep (angler z:[0.65,1], jelly z up to 0.9)
// get dimmed almost to nothing by the depth-darkening below, so they get a minimum brightness that
// ignores depth, like a lure or a jelly's own pulse. The six angler/jelly/rogue/serpent/hunter/eel
// schemes are mood-board palettes (not from the SVGs, which leave these plain) — each an explicit
// lo→hi two-tone gradient rather than one dimmed shade, to actually carry two distinct hues the way
// the references do; the existing holographic iris() shimmer (always on, in LINE_FS/PT_FS) does the
// rest for "iridescent"/"holographic" on top of these. The mood-board six are tuned to the tank's
// glitch-circuit reference still (deep violet, hot pink, cyan, lime, amber, indigo) — each keeps its
// original character (lure-glow, stalker, ribbon elegance, electric predator, bioluminescence) but in
// that family of hues, so they read as native to the repainted void/dock rather than the old teal rig.
const HUE = {
  koi:     { hi: [1.000, 0.722, 0.420] },               // #FFB86B — koi.svg
  manta:   { hi: [1.000, 0.722, 0.420] },               // #FFB86B — Glass Manta.svg
  puffer:  { hi: [1.000, 0.722, 0.420] },                // #FFB86B — Blade Puffer.svg
  worm:    { hi: [1.000, 0.722, 0.420] },               // #FFB86B — butterfly-worm.svg
  dragon:  { hi: [1.000, 0.722, 0.420] },               // #FFB86B — dragoon.svg / winged-dragon.svg
  angler:  { lo: [0.220, 0.040, 0.110], hi: [1.000, 0.750, 0.300], glow: 0.75 },   // #380A1C deep plum body into a #FFBF4C amber lure-glow, from the reference's amber squares; glow kept raised — LINE_FS mixes toward a blue-grey tint by (1-vDim)*0.7, so a low vDim floor was greying out the warm strokes as well as dimming them
  siphon:  { hi: [0.843, 0.859, 0.878] },               // #D7DBE0 — Bead Siphon.svg
  moth:    { hi: [0.843, 0.859, 0.878] },               // #D7DBE0 — Crown Moth.svg
  wisp:    { hi: [0.843, 0.859, 0.878] },               // #D7DBE0 — Lantern Wisp.svg
  pincer:  { hi: [0.843, 0.859, 0.878] },               // #D7DBE0 — Pincer Crawler.svg (species key is "pincer", not "crawler")
  swift:   { hi: [0.843, 0.859, 0.878] },               // #D7DBE0 — Sickle Swift.svg
  leech:   { hi: [0.843, 0.859, 0.878] },               // #D7DBE0 — Studded Leech.svg
  jelly:   { lo: [0.050, 0.080, 0.260], hi: [0.450, 0.950, 0.950], glow: 0.35 },   // #0D1442 into #73F2F2 — deep indigo pulsing up to the reference's cyan
  rogue:   { lo: [0.110, 0.055, 0.230], hi: [0.480, 0.300, 0.950] },   // #1C0E3B into #7A4CF2 — cosmic/shadowy, now the reference's electric violet instead of blue-purple
  serpent: { lo: [0.480, 0.160, 0.320], hi: [1.000, 0.600, 0.780] },   // #7A2952 into #FF99C7 — ribbon elegance, now the reference's hot pink instead of white
  hunter:  { lo: [0.050, 0.100, 0.400], hi: [0.320, 0.550, 1.000] },   // #0D1A66 into #528CFF — electric predator, shifted toward the reference's indigo blue
  eel:     { lo: [0.100, 0.320, 0.550], hi: [0.700, 0.970, 1.000], glow: 0.22 },   // #1A528C into #B2F7FF — white-blue bioluminescence, cooled toward the reference's cyan
};
const DEFAULT_COL_HI = [0.38, 0.898, 0.749]; // the original shared teal (#61E5BF), kept as the default

// ---------- evolution: eat enough and a fish grows into its next stage; the two apexes die of old age
// instead, dropping a carcass that sinks to the bottom and feeds whatever grazes there (wisp, pincer) ----------
// wisp -> swift -> koi -> {manta -> eel, hunter -> rogue}: sizes (swim.len) rise 0.32 / 0.55 / 1.0 / 1.3 / 3.4 / 2.2 / 2.8,
// and both apexes already sit deep in the water column, so "grows bigger, sinks deeper, dies at the bottom" is free.
const EVOLVE = {
  wisp: { next: ['swift'], meals: 1 }, swift: { next: ['koi'], meals: 8 },
  puffer: { next: ['siphon'], meals: 10 }, pincer: { next: ['angler'], meals: 10 },
  'strike-lance': { next: ['angler'], meals: 8 }, 'chain-colony': { next: ['siphon'], meals: 6 },
  koi: { next: ['manta', 'hunter'], meals: 12 },
  angler: { next: ['rogue'], meals: 10 }, serpent: { next: ['eel'], meals: 10 }, jelly: { next: ['manta'], meals: 10 },
  manta: { next: [], meals: 10 }, hunter: { next: [], meals: 8 }, rogue: { next: [], meals: 8 },
  eel: { next: [], meals: 10 }, dragon: { next: [], meals: 12 },
};

// ---- tiers: 1 = common/small (bulk of the population), 2 = mid (an active predator of tier 1),
// 3 = apex/rare (preys on tier 2 and tier 1). Population weights above are split roughly 65/25/10
// across the three. A tier-3 fish that reaches its own meals threshold with nowhere left to evolve
// doesn't just vanish: alongside the usual carcass, it now also seeds a few tier-1 juveniles nearby --
// the loop the old "apex just dies" version was missing.
const TIER1_KEYS = ["wisp","swift","puffer","leech","moth","worm","pincer","carapace-strider","strike-lance","glass-star","comb-drifter","plated-scavenger","frond-serpent","chain-colony","angler-tailed-jelly-af60","dragon-winged-stub-worm-7390","dragon-winged-worm-ed95","koi-winged-dragon-6cce","puffer-plated-angler-25d9","eye-wing"];
const TIER2_KEYS = ["koi","angler","serpent","jelly","siphon"];
const TIER3_KEYS = ["manta","hunter","rogue","eel","dragon"];

window.EcologySpecies = { SPECIES, BEH, ECO, WING, HUE, DEFAULT_COL_HI, EVOLVE, TIER1_KEYS, TIER2_KEYS, TIER3_KEYS };
